-- Barracuda clips: shared shark/fish clips (GreatWhiteClips, re-scaled to this rig's SEG) + its own TORPEDO clip.
local gw = require(script.Parent:WaitForChild("GreatWhiteClips"))
local SEG = 0.5687
local k = SEG / gw.SEG
local clips = {}
for name, c in gw.clips do
	if name ~= "Breach" and name ~= "SharkSense" then
		local keys = {}
		for _, kf in c.keys do
			local pose = {}
			for b, e in kf[2] do
				if #e > 4 then pose[b] = {e[1], e[2], e[3], e[4], e[5] * k, e[6] * k, e[7] * k} else pose[b] = e end
			end
			table.insert(keys, {kf[1], pose})
		end
		clips[name] = {loop = c.loop, keys = keys}
	end
end
